<?php
use Illuminate\Support\Facades\Route;use App\Http\Controllers\{AuthController,ProductionController};
Route::get('/',fn()=>redirect('/dashboard'));Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'show'])->name('login');Route::post('/login',[AuthController::class,'login']);});Route::middleware('auth')->group(function(){Route::post('/logout',[AuthController::class,'logout'])->name('logout');Route::get('/dashboard',[ProductionController::class,'dashboard'])->name('dashboard');Route::get('/production',[ProductionController::class,'verification'])->name('production');Route::post('/production/{item}/verify',[ProductionController::class,'verify'])->name('verify');Route::get('/ready-for-print',[ProductionController::class,'queue'])->name('queue');Route::post('/batches',[ProductionController::class,'batch'])->name('batch.create');Route::get('/batches',[ProductionController::class,'batches'])->name('batches');Route::get('/batches/{batch}',[ProductionController::class,'showBatch'])->name('batch.show');});
